import org.evosuite.runtime.EvoRunner;
import org.evosuite.runtime.EvoRunnerParameters;
import org.evosuite.runtime.ViolatedAssumptionAnswer;
import org.junit.runner.RunWith;

@RunWith(EvoRunner.class)
@EvoRunnerParameters(mockJVMNonDeterminism = true, useVFS = true, useVNET = true, resetStaticState = true, separateClassLoader = false)
public class JsonFormat_ESTest_test31 extends JsonFormat_ESTest_scaffolding {

    @Test(timeout = 4000)
    public void test31() throws Throwable {
        JsonFormat.Shape matchingShape = JsonFormat.Shape.SCALAR;
        Locale frenchLocale = Locale.FRENCH;
        TimeZone falseTimeZone = TimeZone.getTimeZone("FALSE");
        JsonFormat.Features emptyFeatures = JsonFormat.Features.empty();
        Boolean explicitLeniency = Boolean.TRUE;

        JsonFormat.Value formatValue = new JsonFormat.Value(
                "FALSE",
                matchingShape,
                frenchLocale,
                falseTimeZone,
                emptyFeatures,
                explicitLeniency,
                10);

        JsonFormat.Value sameShapeValue = formatValue.withShape(matchingShape);

        assertEquals(10, sameShapeValue.getRadix());
        assertSame(sameShapeValue, formatValue);
        assertTrue(sameShapeValue.hasPattern());
    }
}
